<script setup lang="ts">
import { computed } from 'vue'
import { budgetSpent, categoryPath, localDay, rangeForPreset, transactionShareAmount, transactionInStatistics, statisticsSummary, type LedgerSnapshot, type Transaction } from './ledger'
import { money } from './ledgerViewModels'
import UiIcon from './UiIcon.vue'
import CategoryIcon from './CategoryIcon.vue'
import CategoryStatistics from './CategoryStatistics.vue'
import IncomeExpenseTrend from './IncomeExpenseTrend.vue'
const props = defineProps<{ snapshot: LedgerSnapshot; period: 'week'|'month'|'year' }>()
const emit = defineEmits<{ 'update:period': [value:'week'|'month'|'year']; calendar: []; pin: []; range: [id:string]; 'remove-range': [id:string]; budgets: []; 'create-budget': []; entry: []; import: []; transactions: []; edit: [transaction:Transaction] }>()
const range = computed(() => rangeForPreset(props.period))
const rows = computed(() => props.snapshot.transactions.filter(tx => transactionInStatistics(tx) && new Date(tx.happenedAt) >= range.value.start && new Date(tx.happenedAt) < range.value.end))
const totals = computed(() => statisticsSummary(rows.value))
const periodLabel = computed(() => props.period === 'week' ? '本周' : props.period === 'month' ? '本月' : '本年')
const budgets = computed(() => props.snapshot.budgets.map(budget => {
  const start = budget.periodType === 'monthly' ? new Date(budget.year,(budget.month||1)-1,1) : new Date(`${budget.startDate}T00:00:00`)
  const end = budget.periodType === 'monthly' ? new Date(budget.year,budget.month||1,1) : new Date(`${budget.endDate}T00:00:00`)
  if(budget.periodType !== 'monthly') end.setDate(end.getDate()+1)
  return { ...budget, spent:budgetSpent(props.snapshot,budget,start,end), active: new Date() >= start && new Date() < end }
}))
const activeBudgets = computed(() => budgets.value.filter(budget => budget.active))
const budgetLeft = computed(() => activeBudgets.value.reduce((total,budget)=>total+budget.limitAmount-budget.spent,0))
const recent = computed(() => [...rows.value].sort((a,b)=>b.happenedAt.localeCompare(a.happenedAt)).slice(0,5))
const categoryFor = (id:string|null) => props.snapshot.categories.find(category=>category.id===id)
const expenseDaily = computed(() => { const now=new Date();const days=Math.max(1,Math.round((Math.min(now.getTime(),range.value.end.getTime())-range.value.start.getTime())/86400000)+1);return totals.value.expense/days })
</script>
<template>
  <section class="home-dashboard">
    <div class="home-intro"><div><span class="home-eyebrow">YOUR MONEY, AT A GLANCE</span><h2>每一笔，都心中有数。</h2><p>{{ new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'}) }} · 记录生活，也为下一程留好预算</p></div><button type="button" class="feature-button" @click="emit('import')"><UiIcon name="scan" :size="17"/>截图记账</button></div>
    <div class="home-period-bar"><div class="home-segments" aria-label="统计周期"><button v-for="key in ['week','month','year'] as const" :key="key" type="button" :aria-pressed="period===key" :class="{active:period===key}" @click="emit('update:period',key)">{{ key==='week'?'本周':key==='month'?'本月':'本年' }}</button></div><span class="home-period-dates">{{ localDay(range.start).replaceAll('-','.') }} — {{ localDay(new Date(range.end.getTime()-1)).replaceAll('-','.') }}</span><div class="home-period-actions"><button type="button" class="feature-icon-button" title="置顶统计区间" aria-label="置顶统计区间" @click="emit('pin')"><UiIcon name="pin" :size="17"/></button><button type="button" class="feature-button" @click="emit('calendar')"><UiIcon name="calendar" :size="17"/>收支日历</button></div></div>
    <div v-if="snapshot.pinnedRanges.length" class="home-pinned"><div v-for="item in snapshot.pinnedRanges" :key="item.id"><button type="button" @click="emit('range',item.id)"><UiIcon name="pin" :size="12"/>{{ item.name }}</button><button type="button" :aria-label="`取消置顶${item.name}`" @click="emit('remove-range',item.id)"><UiIcon name="close" :size="13"/></button></div></div>
    <div class="home-summary"><article class="home-expense-card"><header><span>{{ periodLabel }}总支出</span><UiIcon name="expense" :size="22"/></header><strong>{{ money(totals.expense) }}</strong><footer><span>日均支出 <b>{{ money(expenseDaily) }}</b></span><span>{{ rows.length }} 笔收支记录</span></footer></article><article class="home-money-card"><header><span>{{ periodLabel }}总收入</span><i class="home-income-icon"><UiIcon name="income" :size="18"/></i></header><strong class="home-income">{{ money(totals.income) }}</strong><footer>收入的每一份，都值得记录</footer></article><article class="home-money-card"><header><span>{{ periodLabel }}结余</span><i><UiIcon name="wallet" :size="18"/></i></header><strong>{{ money(totals.income-totals.expense) }}</strong><footer>总收入 − 总支出</footer></article></div>
    <p class="statistics-note">按本人份额汇总，同一笔流水只计一次，不计统计的记录已排除。</p>
    <div class="home-mini-stats"><div><i><UiIcon name="budget" :size="19"/></i><span><small>当前预算剩余</small><strong :class="{'home-warning':budgetLeft<0}">{{ money(budgetLeft) }}</strong></span><b>{{ activeBudgets.length }} 个预算</b></div><div><i class="home-saving-icon"><UiIcon name="tag" :size="19"/></i><span><small>{{ periodLabel }}优惠</small><strong>{{ money(totals.discount) }}</strong></span></div><div><i class="home-premium-icon"><UiIcon name="premium" :size="19"/></i><span><small>{{ periodLabel }}溢价</small><strong>{{ money(totals.premium) }}</strong></span></div></div>
    <div class="home-charts"><CategoryStatistics :transactions="rows" :categories="snapshot.categories" :appearance-mode="snapshot.settings.appearanceMode"/><IncomeExpenseTrend :transactions="rows" :start="range.start" :end="range.end" :period="period"/></div>
    <div class="home-bottom"><article class="home-panel"><header class="home-panel-heading"><div><h3>预算进度</h3><p>让每一份计划都有余地</p></div><button type="button" class="feature-text-button" @click="emit('budgets')">管理预算<UiIcon name="chevron" :size="14"/></button></header><div v-if="activeBudgets.length" class="home-budget-list"><div v-for="budget in activeBudgets.slice(0,4)" :key="budget.id"><div><b>{{ budget.name }}</b><small :class="{'home-warning':budget.spent>budget.limitAmount}">{{ (budget.spent/budget.limitAmount*100).toFixed(0) }}%</small></div><div class="home-track"><i :class="{over:budget.spent>budget.limitAmount}" :style="{width:`${Math.min(100,budget.spent/budget.limitAmount*100)}%`}"></i></div><p>已用 {{ money(budget.spent) }}<span>预算 {{ money(budget.limitAmount) }}</span></p></div></div><div v-else class="home-empty small"><span><UiIcon name="budget" :size="25"/></span><b>给生活一个小计划</b><p>{{ snapshot.budgets.length?'当前没有进行中的预算':'设置预算，更从容地安排每月开销' }}</p><button type="button" class="feature-button" @click="emit('create-budget')">新建预算</button></div></article><article class="home-panel"><header class="home-panel-heading"><div><h3>最近记录</h3><p>{{ periodLabel }}的生活足迹</p></div><button type="button" class="feature-text-button" @click="emit('transactions')">全部流水<UiIcon name="chevron" :size="14"/></button></header><div v-if="recent.length" class="home-recent"><button v-for="tx in recent" :key="tx.id" type="button" @click="emit('edit',tx)"><span class="home-recent-icon"><CategoryIcon :name="categoryFor(tx.categoryId)?.icon" :category-name="categoryFor(tx.categoryId)?.name" :color="categoryFor(tx.categoryId)?.color" :flow-type="tx.kind" :size="20"/></span><span><b>{{ tx.title }}</b><small>{{ localDay(tx.happenedAt).slice(5).replace('-','月') }}日 · {{ categoryFor(tx.categoryId)?.name||'未分类' }}</small></span><strong :class="{'home-income':tx.kind==='income'}">{{ tx.kind==='expense'?'−':'+' }}{{ money(transactionShareAmount(tx)) }}</strong></button></div><div v-else class="home-empty small"><span><UiIcon name="book" :size="25"/></span><b>生活值得被记录</b><p>手动记一笔，或导入一张账单截图</p><button type="button" class="feature-button" @click="emit('entry')">开始记账</button></div></article></div>
  </section>
</template>
